function soundInit(){if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(AC)audio=new AC();}audio?.resume();sound=settings.sound;}
function beep(freq=760,dur=.06,volume=.018){if(!sound||!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}
function chargeSound(){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(280,audio.currentTime);o.frequency.exponentialRampToValueAtTime(1400,audio.currentTime+1.9);g.gain.setValueAtTime(.09,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+2);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+1.9);}
function master(){const g=audio.createGain();g.gain.value=1;const comp=audio.createDynamicsCompressor();comp.threshold.value=-10;comp.ratio.value=4;g.connect(comp);comp.connect(audio.destination);return g;}
// Defibrillator discharge: low body thump + electrical crack + short buzz. Loud on purpose.
function shockSound(){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime,out=master();
 const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(140,t);o.frequency.exponentialRampToValueAtTime(38,t+.38);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.95,t+.012);g.gain.exponentialRampToValueAtTime(.001,t+.5);o.connect(g);g.connect(out);o.start(t);o.stop(t+.55);
 const len=Math.floor(audio.sampleRate*.28),buf=audio.createBuffer(1,len,audio.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,3);const n=audio.createBufferSource();n.buffer=buf;const bp=audio.createBiquadFilter();bp.type='bandpass';bp.frequency.value=2200;bp.Q.value=.7;const ng=audio.createGain();ng.gain.value=.9;n.connect(bp);bp.connect(ng);ng.connect(out);n.start(t);
 const z=audio.createOscillator(),zg=audio.createGain();z.type='sawtooth';z.frequency.value=95;zg.gain.setValueAtTime(.32,t);zg.gain.exponentialRampToValueAtTime(.001,t+.16);z.connect(zg);zg.connect(out);z.start(t);z.stop(t+.18);
 if(navigator.vibrate)try{navigator.vibrate(180);}catch{}
 $('stage').classList.remove('shock-flash');void $('stage').offsetWidth;$('stage').classList.add('shock-flash');}
// ---- Sound effects for the vital steps (Web Audio, no files) ----
function noiseBurst(dur=.2,freq=1200,q=.8,vol=.4,type='bandpass',sweepTo=null,delay=0){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime+delay,len=Math.floor(audio.sampleRate*dur),buf=audio.createBuffer(1,len,audio.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const n=audio.createBufferSource();n.buffer=buf;const f=audio.createBiquadFilter();f.type=type;f.frequency.setValueAtTime(freq,t);if(sweepTo)f.frequency.exponentialRampToValueAtTime(sweepTo,t+dur);f.Q.value=q;const g=audio.createGain();g.gain.value=vol;n.connect(f);f.connect(g);g.connect(audio.destination);n.start(t);}
function tone(freq,dur,vol=.08,type='sine',delay=0,slideTo=null){if(!sound||!audio||audio.state!=='running')return;const t=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slideTo)o.frequency.exponentialRampToValueAtTime(slideTo,t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+dur+.02);}
const SFX={
 monitor:()=>{tone(1046,.09,.09,'sine');tone(1318,.12,.09,'sine',.12);},
 pads:()=>{noiseBurst(.08,500,1,.35,'lowpass');noiseBurst(.08,500,1,.35,'lowpass',null,.14);},
 cpr:()=>{for(let i=0;i<3;i++)tone(90,.12,.25,'sine',i*.545,55);},
 drug:()=>{noiseBurst(.45,3000,2,.18,'bandpass',900);tone(660,.08,.05,'sine',.48);},
 iv:()=>{tone(300,.08,.15,'triangle',0,600);tone(880,.1,.07,'sine',.1);},
 bvm:()=>{noiseBurst(.35,700,1.2,.25,'bandpass',300);},
 airway:()=>{tone(1200,.04,.12,'square');tone(523,.15,.08,'sine',.15);tone(784,.2,.08,'sine',.32);},
 lab:()=>{tone(1318,.25,.1,'sine');tone(988,.4,.1,'sine',.22);},
 good:()=>{tone(784,.1,.08,'triangle');tone(988,.1,.08,'triangle',.07);tone(1319,.26,.09,'sine',.14);tone(2637,.2,.03,'sine',.14);},
 wrong:()=>{tone(196,.16,.12,'sawtooth',0,150);tone(147,.24,.12,'sawtooth',.14,110);noiseBurst(.12,180,.8,.25,'lowpass');},
 coin:()=>{tone(988,.07,.07,'square');tone(1319,.18,.07,'square',.07);},
 rosc:()=>{tone(65,.9,.4,'sine',0,98);[523,659,784,1046,1319].forEach((f,i)=>{tone(f,.34,.13,'triangle',i*.12);tone(f*2,.2,.04,'sine',i*.12);});[1046,1319,1568].forEach(f=>tone(f,1.1,.07,'sine',.66));noiseBurst(.9,6000,.6,.08,'highpass',null,.66);},
 alarm:()=>{[0,.18,.36].forEach(d=>tone(932,.12,.11,'square',d));[.62,.8].forEach(d=>tone(698,.14,.11,'square',d));tone(55,.5,.25,'sine',0,40);},
 sting:()=>{tone(49,1.4,.5,'sine',0,36);noiseBurst(1.1,200,.7,.3,'lowpass',2400);tone(1568,.5,.05,'sine',.9);},
 whoosh:()=>{noiseBurst(.28,500,.9,.12,'bandpass',2600);},
 heart:()=>{tone(70,.12,.4,'sine',0,45);tone(60,.14,.3,'sine',.18,40);},
 combo:()=>{tone(1319,.06,.06,'square');tone(1760,.06,.06,'square',.06);tone(2093,.14,.06,'square',.12);},
 temp:()=>{tone(2093,.06,.06,'sine');tone(2093,.06,.06,'sine',.1);},
 warn:()=>{tone(932,.09,.07,'triangle');tone(784,.12,.07,'triangle',.11);},
 clear:()=>{tone(1318,.1,.08,'square');tone(1318,.1,.08,'square',.16);tone(1760,.18,.07,'square',.32);}
};
/* Room sound. A resus bay is never silent: the monitor beeps on every complex, the compressor
   thumps, the flat line nags, and the clock ticks into the rhythm check. All of it is quiet on
   purpose — it should sit under the voices, not fight them. Beeping on every QRS also teaches:
   you can HEAR electrical activity in PEA, and hear it vanish in asystole. */
let sndBeat=1,sndThump=1,sndAsys=-9,sndTick=-9,sndPace=1,sndBreath=-9;
function roomSound(s,dt){if(!sound||!audio||audio.state!=='running'||s.paused||s.ended||document.body.classList.contains('cutscene'))return;
 const comp=(ward?.visualMotion||teamMotion(s)).compressing;
 if(comp){sndThump+=dt*(s.cprRate||110)/60;if(sndThump>=1){sndThump=0;tone(86,.09,.055,'sine',0,54);}}else sndThump=1;
 if(s.monitor&&s.hr>0&&!s.pacing&&!/^VF/.test(s.rhythm)&&s.rhythm!=='TORSADES'){sndBeat+=dt*s.hr/60;if(sndBeat>=1){sndBeat=0;tone(s.spo2!=null&&s.spo2<90?830:1046,.045,.03,'sine');}}else sndBeat=1;
 if(s.pacing&&s.pacerMA>0){sndPace+=dt*(s.pacerRate||70)/60;if(sndPace>=1){sndPace=0;tone(1760,.025,.035,'square');if(s.electricalCapture)tone(1046,.05,.028,'sine',.05);}}else sndPace=1;
 if(s.monitor&&!s.pulse&&s.rhythm==='ASYSTOLE'&&s.t-sndAsys>5){sndAsys=s.t;tone(700,.55,.045,'sine');}
 if(s.intubated&&!s.pulse&&s.t-sndBreath>=6){sndBreath=s.t;noiseBurst(.3,620,1.1,.09,'bandpass',260);}
 const left=120-s.cycle;if(!s.pulse&&s.cpr&&left<=5&&left>0&&s.t-sndTick>=1){sndTick=s.t;tone(1568,.05,.035,'square');}}
const EVENT_SFX={clear:'clear',flatline:'good','flatline-step':'coin','cpr-coached':'combo','rhythm-check':'monitor','pulse-check':'monitor',monitor:'monitor',pads:'pads',cpr:'cpr',medication:'drug',iv:'iv','access-start':'iv',bvm:'bvm',intubate:'airway','labs-result':'lab','temp-result':'temp',etco2:'monitor',bicarb:'drug','calcium-gluconate':'drug','calcium-chloride':'drug','insulin-dextrose':'drug',naloxone:'drug','fluid-bolus':'bvm',glucose:'drug',stabilize:'rosc',capture:'rosc','brady-infusion':'rosc','cpr-fatigue':'alarm','rosc-coach':'alarm',ptx:'alarm',renarc:'alarm',collapse:'alarm',deteriorate:'alarm'};
function chargedTone(){if(!sound||!audio||audio.state!=='running')return;for(let i=0;i<3;i++)setTimeout(()=>beep(1250,.14,.12),i*220);}
function cycleTone(kind){if(!sound||!audio||audio.state!=='running')return;if(kind==='soon'){for(let i=0;i<2;i++)setTimeout(()=>beep(880,.12,.09),i*180);}else{for(let i=0;i<3;i++)setTimeout(()=>{beep(988,.2,.14);setTimeout(()=>beep(740,.2,.14),210);},i*520);}}
