let medLog=[];
function renderGiven(){const box=$('given-box');if(!box||!sim)return;box.innerHTML=medLog.length?`<small>GIVEN SO FAR</small>${medLog.map(m=>`<span><b>${fmt(m.t)}</b> ${m.text}</span>`).join('')}`:'<small>GIVEN SO FAR</small><span class="muted">Nothing yet</span>';}
function renderFindings(s){const box=$('findings-box');if(!box)return;const c=CASES[s.id-1],rows=[];if(s.history)rows.push(['History',c.history]);if(s.exam)rows.push(['Exam',c.exam]);if(s.tempChecked)rows.push(['Temperature',`${s.temp.toFixed(1)} °C`]);const last=k=>[...sim.events].reverse().find(e=>e.action===k)?.text;const ecg=last('ecg12-result');if(ecg)rows.push(['12-lead',ecg]);const us=last('pocus-interpretation')||last('pocus');if(us)rows.push(['Ultrasound',us]);const sk=last('patch')||last('patch-normal');if(sk)rows.push(['Skin',sk]);const html=rows.map(([k,v])=>`<p><b>${k}</b>${v}</p>`).join('')||'<p class="muted">Nothing yet — ask, examine, test.</p>';if(box.innerHTML!==html)box.innerHTML=html;}
function renderLabs(s){const box=$('lab-results');if(!box)return;const rows=Object.keys(LAB_TESTS).filter(k=>s.labResults[k]||s.labDue[k]).map(k=>s.labResults[k]?`<p><b>${LAB_TESTS[k].label}</b><br>${LAB_VALUES[s.id][k]}</p>`:`<p class="pending"><b>${LAB_TESTS[k].label}</b> · pending ${fmt(Math.max(0,s.labDue[k]-s.t))}</p>`);const html=rows.join('')||'<p class="muted">No tests sent yet.</p>';if(box.innerHTML!==html)box.innerHTML=html;document.querySelectorAll('#lab-picker [data-lab]').forEach(b=>{const k=b.dataset.lab,st=s.labResults[k]?'back':s.labDue[k]?'sent':'';if(b.dataset.st!==st){b.dataset.st=st;b.classList.toggle('sent',st==='sent');b.classList.toggle('back',st==='back');}const sm=b.querySelector('small'),txt=st==='back'?'✓ result':st==='sent'?'sent · '+fmt(Math.max(0,s.labDue[k]-s.t)):LAB_TESTS[k].secs+' s';if(sm.textContent!==txt)sm.textContent=txt;});}
// Findings automatically update the 5 Hs / 5 Ts review (the learner can still change any entry).
const autoMarked={},autoWhy={};
const HT_NAMES=['Hypovolemia','Hypoxia','Hydrogen ion (acidosis)','Hypo-/hyperkalemia','Hypothermia','Tension pneumothorax','Tamponade, cardiac','Toxins','Thrombosis, pulmonary','Thrombosis, coronary','Hypoglycemia'];
const HT_STATES=['Not reviewed','Considering','Evidence supports','Less likely'];
function paintHtRow(i){const el=document.querySelector(`#ht-window [data-review="${i}"]`);if(!el)return;el.value=causeReview[i];el.className='rv-'+HT_STATES.indexOf(causeReview[i]);
 const note=document.querySelector(`#ht-window [data-why="${i}"]`);if(note){note.textContent=autoWhy[i]?'↳ '+autoWhy[i]:'';note.hidden=!autoWhy[i];}}
/* The Hs & Ts board keeps itself in step with what the player actually did: every examination,
   lab, scan and treatment decides one row, so the board is a record of the evidence, not a quiz.
   One deterministic verdict per row per tick (later rules win), so nothing flaps back and forth. */
function autoReview(s){if(!sim)return;const L=LAB_VALUES[s.id]||{};
 const num=(key,re)=>{if(!s.labResults[key]||!L[key])return null;const m=L[key].match(re);return m?parseFloat(m[1]):null;};
 const out={},put=(i,value,why)=>{out[i]=[value,why];};
 const ph=num('abg',/pH ([\d.]+)/),lac=num('abg',/lactate ([\d.]+)/),pao2=num('abg',/PaO₂ ([\d.]+)/),paco2=num('abg',/PaCO₂ ([\d.]+)/);
 const k=num('elyte',/K⁺ ([\d.]+)/)??num('abg',/K⁺ ([\d.]+)/),dtx=num('dtx',/DTX ([\d.]+)/);
 if(s.pocusCardiac)put(0,'Considering','subcostal view obtained — judge filling from the IVC');
 if(s.iv&&s.fluidBoluses>0)put(0,'Less likely','fluid bolus given through working access');
 if(pao2!=null&&pao2<60)put(1,'Evidence supports',`blood gas PaO₂ ${pao2}${paco2!=null?` with PaCO₂ ${paco2}`:''} — hypoventilation`);
 if(s.bvm||s.intubated)put(1,'Less likely',s.capno?'ventilated through the tube, position confirmed on waveform capnography':'oxygen and bag-mask ventilation under way');
 if(ph!=null)put(2,ph<7.2?'Evidence supports':'Less likely',`blood gas pH ${ph}${lac!=null?` · lactate ${lac}`:''}`);
 if(s.id===1&&s.history)put(3,'Considering','missed dialysis in the history — send electrolytes');
 if(k!=null)put(3,(k>=6||k<3)?'Evidence supports':'Less likely',`K⁺ ${k} mmol/L`);
 if(s.hyperkTreated)put(3,'Evidence supports','hyperkalaemia treated (calcium ± insulin-dextrose)');
 if(s.tempChecked)put(4,s.temp<35?'Evidence supports':'Less likely',`temperature ${s.temp.toFixed(1)} °C`);
 if(s.pocusLung)put(5,s.ptx?'Evidence supports':'Less likely',s.ptx?'no lung sliding on POCUS':'lung sliding seen on both sides');
 if(s.exam&&s.ptx)put(5,'Evidence supports','unequal breath sounds with falling blood pressure');
 if(s.decompressed||s.drain)put(5,'Evidence supports','needle decompression / chest drain performed');
 if(s.pocusCardiac){put(6,'Less likely','no pericardial effusion on the subcostal view');put(8,'Less likely','no right-ventricular dilation on the subcostal view');}
 if(s.id!==5&&s.history&&s.exam)put(7,'Less likely','nothing in the history or examination points to a toxin');
 if(s.id===5&&s.history)put(7,'Evidence supports','long-term fentanyl patches in the history');
 if(s.patch)put(7,'Evidence supports','fentanyl patches found and removed');
 if(s.naloxone)put(7,'Evidence supports','opioid toxicity reversed with naloxone');
 if(s.labResults.tropt)put(9,s.id===4?'Evidence supports':'Less likely',s.id===4?'troponin T markedly elevated':'troponin T not above the expected range');
 if(s.id===4&&sim.awarded.has('ecg12'))put(9,'Evidence supports','inferior ST elevation on the 12-lead');
 if(dtx!=null)put(10,dtx<70?'Evidence supports':'Less likely',`DTX ${dtx} mg/dL`);
 if(s.glucose)put(10,'Evidence supports','documented hypoglycaemia treated with dextrose 50 %');
 for(const key in out){const i=+key,[value,why]=out[key];
  if(causeReview[i]&&causeReview[i]!=='Not reviewed'&&!autoMarked[i])continue;
  if(autoMarked[i]===value&&autoWhy[i]===why)continue;
  const changed=autoMarked[i]!==value;autoMarked[i]=value;autoWhy[i]=why;causeReview[i]=value;
  if(changed)sim.log('cause-auto',`${HT_NAMES[i]}: ${value} — ${why}`);
  paintHtRow(i);}
 htEvidence();
}

function labAlert(text){const el=$('lab-alert');el.innerHTML=`<b>🧪 LAB RESULT</b><span>${escape(text)}</span>`;el.hidden=false;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');clearTimeout(labAlert.t);labAlert.t=setTimeout(()=>{el.hidden=true;},7000);SFX.lab();sayTeam(text,'Lab result. '+shortSpeech(text.replace(/^[^:]*: /,'')));$('lab-status').classList.remove('flash');void $('lab-status').offsetWidth;$('lab-status').classList.add('flash');}
