function htEvidence(){const el=document.getElementById('ht-evidence');if(!el)return;const hit=HT_NAMES.map((n,i)=>[n,i]).filter(([,i])=>causeReview[i]==='Evidence supports');el.innerHTML=hit.length?`<b>Evidence so far:</b> ${hit.map(([n])=>escape(n)).join(' · ')}`:'<b>Evidence so far:</b> nothing points to a cause yet — examine, send labs, scan, check the temperature.';el.className='ht-evidence'+(hit.length?' hit':'');}
function htRow([i,label]){const v=causeReview[i]||'Not reviewed',idx=HT_STATES.indexOf(v);return `<label>${label}<select data-review="${i}" aria-label="${label}" class="rv-${idx}">${HT_STATES.map(o=>`<option ${v===o?'selected':''}>${o}</option>`).join('')}</select><i class="ht-why" data-why="${i}"${autoWhy[i]?'':' hidden'}>${autoWhy[i]?'↳ '+escape(autoWhy[i]):''}</i></label>`;}
/* Flat-line protocol game: the defibrillator front panel. Re-seat the loose electrode, turn the
   gain up, look at a second lead. It runs in real time, so compressions carry on while you work. */
let flTrace=null,flLoose='LA';
const FL_KEYS=['cable','gain','lead'];
function closeFlatline(){flTrace?.observer.disconnect();flTrace=null;document.getElementById('fl-game')?.remove();}
function flatlineGame(){if(!sim||sim.s.ended)return;markPlayerAction();closeFlatline();
 flLoose=['RA','LA','LL'][Math.floor(Math.random()*3)];
 const el=document.createElement('div');el.id='fl-game';
 el.innerHTML=`<div class="fl-head"><div><b>📉 FLAT-LINE PROTOCOL</b><small>Asystole is never shocked — prove the flat line is real. Compressions keep going.</small></div><button class="fl-close" aria-label="Close">✕</button></div>
 <div class="fl-screen"><canvas id="fl-ecg"></canvas><i id="fl-flag">LEAD OFF?</i></div>
 <ol class="fl-steps">
  <li data-fl="cable"><span class="fl-num">1</span><div><b>Patient cable &amp; electrodes</b><small id="fl-cable-note">One electrode is flashing — tap it to re-seat it.</small><div class="fl-row">${['RA','LA','LL'].map(k=>`<button type="button" data-dot="${k}">${k}</button>`).join('')}</div></div></li>
  <li data-fl="gain"><span class="fl-num">2</span><div><b>Turn the gain up</b><small id="fl-gain-note">Magnify the baseline: fine VF can hide at the standard gain.</small><div class="fl-row">${[1,2].map(g=>`<button type="button" data-gain="${g}">×${g} · ${10*g} mm/mV</button>`).join('')}</div></div></li>
  <li data-fl="lead"><span class="fl-num">3</span><div><b>Check a second lead</b><small id="fl-lead-note">A flat line in one vector can be an artefact. Look down another.</small><div class="fl-row">${['II','I','III'].map(l=>`<button type="button" data-lead="${l}">Lead ${l}</button>`).join('')}</div></div></li>
 </ol>
 <div id="fl-verdict" hidden></div>`;
 $('stage').appendChild(el);flTrace=new Trace($('fl-ecg'),{seconds:4,gain:1,lead:'II'});
 el.querySelector('.fl-close').onclick=closeFlatline;
 const done={...sim.s.flatlineSteps};
 const paint=()=>{const next=FL_KEYS.find(k=>!done[k]);for(const k of FL_KEYS){const li=el.querySelector(`[data-fl="${k}"]`);li.classList.toggle('done',!!done[k]);li.classList.toggle('active',k===next);}
  $('fl-flag').hidden=!!done.cable;el.querySelectorAll('[data-dot]').forEach(b=>b.classList.toggle('loose',!done.cable&&b.dataset.dot===flLoose));};
 const finish=()=>{const r=sim.s.rhythm,v=$('fl-verdict');v.hidden=false;
  const asys=r==='ASYSTOLE',shockable=['VF','VF_FINE','VF_COARSE','VT','TORSADES'].includes(r);
  v.className=asys?'ok':'warn';
  v.innerHTML=asys?`<b>TRUE ASYSTOLE · DO NOT SHOCK</b><small>Cable intact, gain ×2, flat in a second lead. High-quality CPR, epinephrine 1 mg IV/IO as soon as possible and then every 3–5 min, rhythm check every 2 minutes, and keep hunting the cause.</small><div class="fl-row"><button type="button" data-go="resume-cpr">▶ Resume CPR</button><button type="button" data-go="epi">💉 Epinephrine</button><button type="button" data-go="ht">🧩 Hs &amp; Ts</button></div>`
   :shockable?`<b>THIS IS NOT A FLAT LINE</b><small>There is a shockable rhythm on the screen. Charge and shock now — the protocol has just ruled out an artefact.</small><div class="fl-row"><button type="button" data-go="defib">⚡ Defibrillator</button></div>`
   :`<b>COMPLEXES ARE PRESENT · PEA, NOT ASYSTOLE</b><small>Electrical activity without a pulse. No shock: carry on with CPR, epinephrine and the reversible causes.</small><div class="fl-row"><button type="button" data-go="resume-cpr">▶ Resume CPR</button><button type="button" data-go="ht">🧩 Hs &amp; Ts</button></div>`;
  if(sound)asys?SFX.good():SFX.alarm();
  v.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{const g=b.dataset.go;markPlayerAction();closeFlatline();
   if(g==='resume-cpr')orderAction('resume-cpr');else if(g==='epi'){openPanel('meds');selectDrug('epinephrine');}else if(g==='ht')openHT();else openPanel('electrical');});
  const ev=sim.events.at(-1);if(ev)toast(ev.text,ev.kind==='bad');setTimeout(()=>v.scrollIntoView({block:'nearest',behavior:'smooth'}),60);};
 const mark=k=>{if(done[k])return;done[k]=true;sim.action('flatline-step',{step:k});paint();if(FL_KEYS.every(x=>done[x]))finish();};
 el.querySelectorAll('[data-dot]').forEach(b=>b.onclick=()=>{markPlayerAction();if(done.cable)return;
  if(b.dataset.dot!==flLoose){$('fl-cable-note').textContent=`${b.dataset.dot} is making good contact. Look for the one that is flashing.`;if(sound)SFX.wrong();return;}
  $('fl-cable-note').textContent=`${flLoose} re-seated: the cable and all three electrodes are connected, so this flat line is not a lead-off artefact.`;mark('cable');});
 el.querySelectorAll('[data-gain]').forEach(b=>b.onclick=()=>{markPlayerAction();const g=+b.dataset.gain;if(flTrace)flTrace.gain=g;
  el.querySelectorAll('[data-gain]').forEach(x=>x.classList.toggle('active',x===b));
  if(g<2){$('fl-gain-note').textContent='That is the standard gain. Double it to magnify the baseline.';return;}
  $('fl-gain-note').textContent='Gain ×2 (20 mm/mV): the baseline is magnified and there is still no organised complex, so this is not fine VF.';mark('gain');});
 el.querySelectorAll('[data-lead]').forEach(b=>b.onclick=()=>{markPlayerAction();const l=b.dataset.lead;if(flTrace)flTrace.lead=l;
  el.querySelectorAll('[data-lead]').forEach(x=>x.classList.toggle('active',x===b));
  if(l==='II'){$('fl-lead-note').textContent='Lead II is the one already on the monitor. Try lead I or III.';return;}
  $('fl-lead-note').textContent=`Lead ${l}: the same flat line down a second vector.`;mark('lead');});
 paint();if(FL_KEYS.every(k=>done[k]))finish();}
