 if($('give-med'))$('give-med').onclick=()=>{const drug=$('drug').value,ok=teamOrder(`${drug} ${$('dose').value} ${$('unit').value} ${$('route').value}`,()=>sim.med(drug,$('dose').value,$('unit').value,$('route').value),'Medication nurse');if(ok){sim.s.medAnimUntil=sim.s.t+3;const nm=$('drug').selectedOptions[0]?.textContent||drug,d=$('dose').value;medLog.push({t:sim.s.t,text:`${nm}${d&&d!=='titrate'?' '+d+' '+$('unit').value:''} ${$('route').value}`});renderGiven();$('order-sheet').hidden=true;document.querySelectorAll('.mc-card').forEach(c=>c.classList.remove('active'));focusCamera('iv',3);}if(ok&&drug==='adenosine')adenosineAnimation();else if(ok&&!['sedation','dopamine','epi-infusion','naloxone-infusion'].includes(drug)&&!procedureRunning){const name=$('drug').selectedOptions[0]?.textContent||drug;procedureRunning=playProcedure($('stage'),'push',{isPaused:()=>sim.s.paused,label:`${name} ${$('dose').value} ${$('unit').value} ${$('route').value}`,onDone:()=>{procedureRunning=null;}});}};
