function openVagal(){openPanel('resus');$('drawer-kicker').textContent='VAGAL MANEUVER';$('drawer-title').textContent='Choose a vagal maneuver';
 $('drawer-content').innerHTML=`<p>For a <b>stable, regular narrow-complex tachycardia</b>. Keep the monitor running and record the rhythm during the maneuver.</p>
 <button class="vagal-card" data-vagal="valsalva"><b>🫁 Modified Valsalva — syringe (REVERT)</b><small>Blow into a 10 mL syringe for 15 s at 45°, then lie flat with legs raised 45° for 15 s. First choice: most effective vagal maneuver.</small></button>
 <button class="vagal-card" data-vagal="carotid"><b>✋ Carotid sinus massage</b><small>Listen for a bruit first. Firm massage at the angle of the jaw on ONE side for 5–10 s. Avoid with a bruit, prior stroke/TIA or in older patients.</small></button>
 <div class="info-box">Unstable patient (hypotension, altered mental status, chest pain, heart failure)? Skip vagal maneuvers → synchronized cardioversion.</div>`;
 $('drawer-content').querySelectorAll('[data-vagal]').forEach(b=>b.onclick=()=>startVagal(b.dataset.vagal));}
let procedureRunning=null;
function startVagal(type){const s=sim.s;if(s.paused||s.ended)return;if(!s.pulse||s.rhythm!=='SVT'||s.unstable){teamOrder('vagal maneuver',()=>sim.action('vagal',{type}));return;}
 if(procedureRunning)return toast('A procedure is already in progress.');closePanel();ward?.cameraPreset('patient');s.vagalAnim=type;
 sayTeam(type==='carotid'?'Carotid sinus massage, right side. Listening for a bruit first.':'Modified Valsalva. Blow into the syringe, then legs up.');
 procedureRunning=playProcedure($('stage'),type,{isPaused:()=>sim.s.paused,hr:s.hr,onDone:()=>{procedureRunning=null;s.vagalAnim=null;if(!sim.s.ended)teamOrder(type==='carotid'?'carotid sinus massage':'modified Valsalva',()=>sim.action('vagal',{type}));}});}
