/* Short cinematic brief before the clock starts. The simulation is held paused until it ends or is skipped. */
let cutsceneTimers=[];
function endCutscene(){if(!document.body.classList.contains('cutscene'))return;if(sim&&sim.c.tutorial&&!tut)setTimeout(tutStart,500);cutsceneTimers.forEach(clearTimeout);cutsceneTimers=[];$('cutscene').classList.add('out');document.body.classList.remove('cutscene');if(sim&&!sim.s.ended){sim.s.paused=false;lastPlayerAt=sim.s.t;}ward?.cameraPreset('overview');setTimeout(()=>{$('cutscene').hidden=true;$('cutscene').classList.remove('out');},650);update();}
function playCutscene(){if(!sim)return;const c=CASES[sim.s.id-1],cs=$('cutscene');const parts=c.brief.split(/(?<=[.!?])\s+/).filter(Boolean).slice(0,2);const lines=[...parts,'You are the team leader.'];
 sim.s.paused=true;document.body.classList.add('cutscene');cs.hidden=false;cs.classList.remove('out');$('cs-kicker').textContent=`Case 0${c.id} · ${c.title}`;
 const cams=['intro','patient','monitor','overview'],step=settings.reduced?1500:2300;
 lines.forEach((text,i)=>cutsceneTimers.push(setTimeout(()=>{const h=$('cs-line');h.textContent=text;h.classList.remove('in');void h.offsetWidth;h.classList.add('in');ward?.cameraPreset(cams[Math.min(i,cams.length-1)]);if(sound){i===lines.length-1?SFX.sting():SFX.heart();if(i===0)[0,.35,.7].forEach(d=>tone(960,.1,.12,'square',d));}},i*step)));
 cutsceneTimers.push(setTimeout(endCutscene,lines.length*step+500));}
$('cs-skip').onclick=endCutscene;window.skipCutscene=endCutscene;
/* Brief zoom on whatever the team is doing, then back to the view the player chose. */
