function focusCamera(name,secs=3){if(!ward||settings.reduced)return;ward.cameraPreset(name);clearTimeout(camTimer);camTimer=setTimeout(()=>{if(ward&&ward.presetName===name)ward.cameraPreset(userPreset);},secs*1000);}
const ACTION_FOCUS={pads:['chest',3.5],charge:['defib',2.5],clear:['overview',2],shock:['chest',2.5],bvm:['airway',3],oxygen:['airway',2.5],'insert-iv':['iv',3],'insert-io':['iv',3],history:['family',3],switch:['cpr',3],exam:['patient',3],pulse:['patient',2.5]};
function markPlayerAction(){if(sim)lastPlayerAt=sim.s.t;hideIdleHint();}
