function refreshPanelSoon(){setTimeout(()=>{if(sim&&!sim.s.ended&&['resus','airway','assess'].includes(panel)&&!practiceUpdate&&!$('drawer').hidden){const st=$('drawer').scrollTop;openPanel(panel);$('drawer').scrollTop=st;}},80);}
function orderAction(action){
 markPlayerAction();if(ACTION_FOCUS[action]&&sim&&!sim.s.paused)focusCamera(...ACTION_FOCUS[action]);if(action==='cpr'&&sim&&!sim.s.cpr&&!sim.s.pulse)focusCamera('cpr',3);
 if(action==='flatline'&&sim&&!sim.s.paused&&!sim.s.ended){closePanel();flatlineGame();return true;}
 if(action==='shock'&&sim.s.charged&&(!sim.s.clear||sim.s.cpr)&&!sim.s.paused&&!sim.s.ended){if(sim.action('unsafe-discharge')){saveSession();try{localStorage.setItem('resus-last-safety-event',JSON.stringify(currentReport()));}catch{};airwayProcedure.cancel();closePanel();safetyRemaining=5;if(ward)ward.safetyRemaining=5;$('stage').classList.add('safety-event');shockSound();sayTeam('Unsafe shock! Clear all patient contact before discharge. Restarting this case.');}return false;}
 if(action==='shock'){const ok=teamOrder(action,()=>sim.action(action));if(ok){shockSound();if(!sim.s.pulse){$('drawer-content').insertAdjacentHTML('afterbegin','<button id="post-shock-cpr" class="primary wide">Resume CPR now</button>');$('post-shock-cpr').onclick=()=>orderAction('resume-cpr');}}return ok;}
 if(action==='pocus'){return teamOrder('focused ultrasound report',()=>sim.action('pocus'),'Assessment clinician');}
 if(action==='vagal-menu'){openVagal();return false;}
 if(action==='auscultate'){if(sim.s.paused||sim.s.ended)return false;if(window.autoProcedures)return sim.action('auscultate');auscultateAnimation();return true;}
 if(action==='patch'&&sim.s.id===5&&!sim.s.patch&&!sim.s.paused&&!sim.s.ended){closePanel();ward?.cameraPreset('patient');procedureRunning?.skip();sayTeam('Log-rolling the patient. Inspecting the skin.');sim.s.patchAnim=true;playPatchHunt($('stage'),{onPeel:(n,total)=>{markPlayerAction();if(sound){noiseBurst(.22,2600,1.4,.3,'bandpass',700);tone(880+n*120,.09,.07,'triangle',.16);if(n===total)SFX.good();}toast(n===total?`All ${total} fentanyl patches removed ✓`:`Patch ${n} of ${total} removed — keep looking`);},onDone:()=>{sim.s.patchAnim=false;teamOrder('remove all fentanyl patches',()=>sim.action('patch'));},onCancel:n=>{sim.s.patchAnim=false;if(n)sim.log('patch-partial',`${n} patch(es) removed, but the skin check was not finished — more may remain`,'warn');}});return true;}
 if(action==='analyze'){if(sim.s.paused||sim.s.ended)return false;if(!sim.s.monitor)return sim.action('rhythm-check');if(sim.s.cpr)sim.action('cpr');const ok=sim.action('rhythm-check');if(ok)rhythmPicker();return ok;}
 if(action!=='intubate'||sim.s.intubated||!sim.s.bvm)return teamOrder(action,()=>sim.action(action));
 if(airwayProcedure.start(sim.s.session)){sayTeam('Airway: Intubating. Compressions continue.');sim.log('airway-order','Airway clinician intubating • Compressions continue');focusCamera('airway',4);return true;}
 toast('The airway team is already carrying out this order.');return false;
}
$('dock').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(!b)return;panel===b.dataset.panel?closePanel():openPanel(b.dataset.panel);});
$('drawer-content').addEventListener('click',e=>{const a=e.target.closest('[data-action]'),b=e.target.closest('[data-targeted]');if(a){const accepted=orderAction(a.dataset.action);refreshPanelSoon();if(a.dataset.action==='commands')document.querySelectorAll('.temperature-field').forEach(e=>e.hidden=!sim.s.commandsChecked||sim.s.conscious);if(a.dataset.action==='rhythm-check'&&accepted)rhythmPicker();if(['history','exam','labs','ecg12','temp','stability','cath','dialysis','repeat-k','commands'].includes(a.dataset.action)){const ev=sim.events.at(-1);toast(ev.text,ev.kind==='bad');}}if(b)teamOrder(b.textContent,()=>sim.targeted(b.dataset.targeted));});
// After the learner names a rhythm, show the matching ACLS branch with one-tap next steps.
function protocolPanel(choice){const P={
 shockable:['Shockable: VF / pulseless VT',['Charge 200 J UNSYNC while compressions continue','Hands off — clear — SHOCK','Resume CPR immediately for 2 minutes','Epinephrine after the 2nd shock · amiodarone / lidocaine after the 3rd'],[['open-electrical','⚡ Open defibrillator'],['resume-cpr','▶ Resume CPR']]],
 pea:['PEA: non-shockable — do NOT shock',['Organised complexes with no pulse: the electricity works, the pump does not — look for why','Resume CPR immediately — push hard, push fast, change compressor every 2 min','Epinephrine 1 mg IV/IO as soon as possible, then every 3–5 min','Search for reversible causes: Hs &amp; Ts, glucose included','Rhythm check every 2 minutes · if the complexes disappear, run the flat-line protocol before you believe the flat line'],[['resume-cpr','▶ Resume CPR'],['open-epi','💉 Epinephrine'],['open-ht','🧩 Hs &amp; Ts'],['flatline','📉 Flat-line protocol']]],
 asystole:['Asystole protocol — flat line, do NOT shock',['<b>Flat-line protocol first</b> — a flat screen can be equipment, not the patient: re-seat the patient cable and electrodes (look for a lead off), turn the gain up to ×2, and check a second lead (I or III)','Asystole is <b>never</b> shocked, and there is no role for routine pacing in asystole','Resume CPR immediately — push hard, push fast, change compressor every 2 min','Epinephrine 1 mg IV/IO as soon as possible, then every 3–5 min','Treat reversible causes: Hs &amp; Ts, glucose included · rhythm check every 2 minutes'],[['flatline','📉 Flat-line protocol'],['resume-cpr','▶ Resume CPR'],['open-epi','💉 Epinephrine'],['open-ht','🧩 Hs &amp; Ts']]],
 organized:['Organized rhythm — is there a pulse?',['Check the carotid pulse (≤10 s)','Pulse present → ROSC / post-arrest care','No pulse → this is PEA: resume CPR and give epinephrine'],[['pulse','✋ Check pulse'],['resume-cpr','▶ Resume CPR']]],
 brady:['Bradycardia algorithm',['Check pulse and perfusion (BP, mental status, chest pain)','Atropine 1 mg IV, repeat every 3–5 min (max 3 mg)','If ineffective: transcutaneous pacing or dopamine / epinephrine infusion','Expert consultation'],[['pulse','✋ Pulse & BP'],['open-atropine','💉 Atropine'],['open-electrical','⚡ Pacing']]],
 narrow:['Tachycardia algorithm',['Check pulse and stability (BP, mental status, chest pain, heart failure)','Stable regular narrow QRS: vagal maneuver → adenosine 6 mg → 12 mg','Unstable: synchronized cardioversion 100 J'],[['pulse','✋ Pulse & BP'],['vagal-menu','🫁 Vagal maneuver'],['open-adenosine','💉 Adenosine'],['open-electrical','⚡ Cardioversion']]]}[choice];
 if(!P)return openPanel('electrical');$('drawer-kicker').textContent='ACLS NEXT STEPS';$('drawer-title').textContent=P[0];
 $('drawer-content').innerHTML=`${sim.s.mode==='guided'?`<ol class="protocol-steps">${P[1].map(x=>`<li>${x}</li>`).join('')}</ol>`:''}<div class="action-grid protocol-actions">${P[2].map(([a,l])=>`<button data-protocol="${a}" class="${a==='resume-cpr'?'primary':''}">${l}</button>`).join('')}</div>`;
 $('drawer-content').querySelectorAll('[data-protocol]').forEach(b=>b.onclick=()=>{const a=b.dataset.protocol;if(a==='open-electrical')return openPanel('electrical');if(a==='open-investigate')return openPanel('investigate');if(a==='open-ht')return openHT();if(a.startsWith('open-')){const drug=a.slice(5)==='epi'?'epinephrine':a.slice(5);openPanel('meds');selectDrug(drug);return;}orderAction(a);});}
function rhythmPicker(){
 reviewTrace?.observer.disconnect();reviewTrace=null;
 if(!sim?.s.monitor){toast('Attach the monitor before interpreting the tracing.');return;}
 practiceUpdate=null;$('play-layout').classList.add('panel-open');$('drawer').hidden=false;panel='rhythm';$('drawer-kicker').textContent='ECG REVIEW';
 const items=[['shockable','VF / pulseless VT'],['pea','PEA — organized rhythm, no pulse'],['asystole','Asystole (flat line)'],['organized','Organized rhythm — check pulse'],['brady','Bradycardia / heart block'],['narrow','Narrow-complex tachycardia']];
 // Treatment drawer intentionally leaves the clinical clock running.
 $('drawer-title').textContent='Interpret the tracing';$('drawer-content').innerHTML='<canvas id="review-ecg" aria-label="Large ECG interpretation strip"></canvas><p>Record your interpretation, then reassess the patient. CPR artifact can obscure the tracing; use a brief scheduled rhythm check when indicated.</p><div class="action-grid">'+items.map(([id,label])=>`<button data-identify="${id}">${label}</button>`).join('')+'</div>';
 $('drawer').scrollTop=0;reviewTrace=new Trace($('review-ecg'),{seconds:6,gain:2});
 $('drawer-content').querySelectorAll('[data-identify]').forEach(b=>b.onclick=()=>{sim.action('rhythm-answer',{value:b.dataset.identify});protocolPanel(b.dataset.identify);});
}

let chosenVoice=null,femaleVoice=null;
/* The team voice is the resus leader beside you: male, and as close to a real recorded voice as the
   device has. "Natural"/"Online" voices are neural and sound far less synthetic, so they come first;
   named platform voices next (Daniel/Alex on Apple, Guy/Ryan/David on Windows, Google UK Male on
   Chrome); any male-sounding English voice after that. The patient and family keep a second,
   different voice so the room does not sound like one person talking to himself. */
const VOICE_MALE=[/Guy Online \(Natural\)/i,/Ryan Online \(Natural\)/i,/Brian Online \(Natural\)/i,/Christopher Online \(Natural\)/i,/Natural.*\b(Guy|Ryan|Brian|Christopher|Davis|Tony|Andrew)\b/i,/Google UK English Male/i,/^Daniel$/i,/^Alex$/i,/^Aaron$/i,/^Oliver$/i,/^Rishi$/i,/^Tom$/i,/Microsoft (David|Mark|George|James)\b/i,/\b(male|man)\b/i];
const VOICE_FEMALE=[/Aria Online \(Natural\)/i,/Jenny Online \(Natural\)/i,/Sonia Online \(Natural\)/i,/Natural.*\b(Aria|Jenny|Sonia|Michelle|Emma)\b/i,/Google UK English Female/i,/^Samantha$/i,/^Karen$/i,/^Moira$/i,/^Serena$/i,/Microsoft (Zira|Hazel|Susan)\b/i,/\b(female|woman)\b/i];
function matchVoice(list,voices){for(const re of list){const hit=voices.find(v=>re.test(v.name));if(hit)return hit;}return null;}
function pickVoice(){const all=speechSynthesis.getVoices(),v=all.filter(x=>/^en/i.test(x.lang));if(!v.length)return;
 chosenVoice=matchVoice(VOICE_MALE,v)||v.find(x=>/natural|online/i.test(x.name))||v[0]||null;
 femaleVoice=matchVoice(VOICE_FEMALE,v.filter(x=>x!==chosenVoice))||v.find(x=>x!==chosenVoice)||chosenVoice;}
/* A line delivered at exactly the same pitch and speed every time is what makes a synthetic voice
   sound synthetic, so each call-out gets a small, stable variation. */
function speakAs(text,voice,{rate=1,pitch=1,jitter=true}={}){if(!voiceEnabled||!('speechSynthesis' in window)||!text)return;
 speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=voice?.lang||'en-US';if(voice)u.voice=voice;
 const n=jitter?(text.length%7)/100:0;u.rate=rate+n;u.pitch=pitch-n/2;u.volume=1;speechSynthesis.speak(u);}
if('speechSynthesis' in window){pickVoice();speechSynthesis.onvoiceschanged=pickVoice;}
/* Short, clinical call-outs: no role names, first clause only — and said the way a person says it.
   Speech engines read "1 mg IV/IO" and "ETCO₂" as letter soup, which is most of what makes a voice
   sound like a machine, so the symbols and abbreviations become spoken words first. */
const SAY=[[/ETCO₂/g,'end tidal CO2'],[/SpO₂/g,'sats'],[/PaCO₂/g,'P a CO2'],[/HCO₃⁻/g,'bicarb'],[/CO₂/g,'CO2'],[/O₂/g,'oxygen'],[/K⁺/g,'potassium'],[/\b1 mg\b/g,'1 milligram'],[/\b1 mcg\b/g,'1 microgram'],
 [/\bIV\/IO\b/g,'I V or I O'],[/\bIO\b/g,'I O'],[/\bIV\b/g,'I V'],[/\bBVM\b/g,'bag mask'],[/\bETT\b/g,'tube'],[/\bDTX\b/g,'bedside glucose'],
 [/\bmg\b/g,'milligrams'],[/\bmcg\b/g,'micrograms'],[/\bmL\b/gi,'mils'],[/\bJ\b/g,'joules'],[/\bmA\b/g,'milliamps'],[/\bmmHg\b/g,''],
 [/\bPEA\b/g,'P E A'],[/\bCPR\b/g,'C P R'],[/\bROSC\b/g,'ross'],[/\bECG\b/g,'E C G'],[/\b12-lead\b/gi,'twelve lead'],
 [/\bdo not\b/gi,"don't"],[/\bcannot\b/gi,"can't"],[/\bit is\b/gi,"it's"],[/\bwe are\b/gi,"we're"],[/\bthat is\b/gi,"that's"],
 [/\s*·\s*/g,', '],[/\s*—\s*/g,', '],[/\s{2,}/g,' ']];
function shortSpeech(text){let t=String(text).split(/ • |\. |\.$/)[0];t=t.replace(/^[A-Z][a-z ]{2,18}:\s*/,'');
 for(const [re,to] of SAY)t=t.replace(re,to);return t.replace(/\s+/g,' ').trim().slice(0,110);}
function sayTeam(text,spoken){$('team-caption').querySelector('p').textContent=text;const line=spoken??shortSpeech(text);const urgent=/\b(clear|shock|stop|now|pulse|arrest|charging)\b/i.test(line);speakAs(line,chosenVoice,{rate:urgent?1.1:1.02,pitch:.92});}
function teamOrder(label,perform,role){
 markPlayerAction();
 if(sim.s.paused||sim.s.ended){sayTeam('Team: Practice is paused or finished. Order not carried out.');return false;}
 role=role||(['insert-iv','insert-io'].includes(label)?'Medication nurse':['bvm','oxygen','intubate'].includes(label)?'Airway':['cpr','switch'].includes(label)?'Compressor':['shock','clear','pads'].includes(label)?'Defibrillator operator':'Team member');
 const readable=({cpr:sim.s.cpr?'pause compressions':'start compressions',bvm:'provide bag-mask ventilation',monitor:'attach monitor',iv:'establish vascular access',etco2:'attach ETCO₂',temp:'check temperature',flatline:'check flat line',pulse:'check pulse',monitor:'attach monitor',pads:'apply pads','insert-iv':'insert a peripheral IV','insert-io':'insert an IO needle','rhythm-check':'check rhythm',clear:'confirm hands clear'})[label]||label;
 const accepted=perform();const result=label==='shock'&&accepted!==false?`Shock ${sim.s.shocks} delivered at ${sim.s.energy} joules. ${sim.events.at(-1)?.text||''}`:sim.events.at(-1)?.text||'Order recorded';
 sayTeam(`${readable[0].toUpperCase()+readable.slice(1)} — ${accepted===false?'not done: ':''}${result}`,accepted===false?`Cannot. ${shortSpeech(result)}`:label==='shock'?`Shock delivered. ${sim.s.pulse?'':'Resume CPR.'}`:`${readable[0].toUpperCase()+readable.slice(1)}. Done.`);
 return accepted;
}
$('voice-toggle').onclick=()=>{voiceEnabled=!voiceEnabled;$('voice-toggle').textContent=voiceEnabled?'Voice on':'Voice off';$('voice-toggle').setAttribute('aria-pressed',String(voiceEnabled));if(!voiceEnabled)window.speechSynthesis?.cancel();else sayTeam('Team ready. We will repeat your orders and report the result.');};
$('interpret-ecg').onclick=()=>orderAction('analyze');$('attach-etco2').onclick=()=>orderAction('etco2');$('coach-cpr').onclick=()=>{markPlayerAction();openPractice('cpr');};$('flatline-qa').onclick=()=>{markPlayerAction();flatlineGame();};
/* Cartoon speech bubble pinned to a team member: a light-hearted nudge when breathing is being forgotten. */
let bubbleWho=null,bubbleUntil=0,bubbleBeat=0;
function teamBubble(who,text,go='resus',secs=7){if(!ward)return;bubbleWho=who;bubbleUntil=performance.now()+secs*1000;const b=$('bubble');b.textContent=text;b.dataset.go=go;b.hidden=false;if(sound){tone(740,.07,.07,'triangle');tone(988,.09,.07,'triangle',.08);tone(659,.12,.07,'triangle',.18);}$('team-caption').querySelector('p').textContent=text;}
function placeBubble(){const b=$('bubble');if(b.hidden)return;if(performance.now()>bubbleUntil||!sim||sim.s.ended||screen!=='play'){b.hidden=true;return;}const p=ward?.screenPoint(ward[bubbleWho]);if(!p||!p.visible){b.style.left='50%';b.style.top='90px';return;}const w=$('stage').clientWidth;const hud=$('right-hud'),lim=hud&&hud.offsetWidth?hud.getBoundingClientRect().left-$('stage').getBoundingClientRect().left-135:w-130;b.style.left=Math.max(130,Math.min(lim,p.x))+'px';b.style.top=Math.max(70,p.y)+'px';}
setInterval(placeBubble,60);$('bubble').onclick=()=>{markPlayerAction();$('bubble').hidden=true;openPanel($('bubble').dataset.go);};
const BUBBLES=[
 [s=>!s.pulse&&s.firstCPR!==null&&!s.bvm&&s.arrestTime>=35,'airway','Boss… the patient is turning a lovely shade of blue. Shall I breathe for them?'],
 [s=>!s.pulse&&s.firstCPR!==null&&!s.bvm&&s.arrestTime>=75,'bagger','I am holding this bag like a handbag. May I squeeze it, please?'],
 [s=>!s.pulse&&s.firstCPR!==null&&!s.bvm&&s.arrestTime>=125,'airway','The lungs just called. They would like some air. Any air.'],
 [s=>s.pulse&&!s.rosc&&s.rr>0&&s.rr<10&&!s.bvm&&s.t>=25,'airway','She breathes about as often as I get a coffee break. Bag-mask?'],
 [s=>!s.pulse&&s.bvm&&!s.intubated&&s.arrestTime>=240,'airway','My arms are getting a workout with this mask. A tube would be lovely — when you are ready.'],
 [s=>s.intubated&&!s.capno&&s.t-(s.intubatedAt||0)>=12,'airway','Tube is in… I think. A capnography trace would help me sleep tonight.'],
 [s=>s.intubated&&s.capno&&!s.pulse&&s.t-(s.intubatedAt||0)>=70,'bagger','Still one breath every 6 seconds over here. Ten a minute, and nobody stops pushing.'],
 [s=>!s.pulse&&s.cpr&&s.capno&&s.etco2<10&&s.arrestTime>=150,'compressor','My ETCO₂ is sulking below 10. Coach me — rate and depth, boss.']];
function bubbleTick(){if(tut||!sim||screen!=='play'||sim.s.ended||sim.s.paused||!$('bubble').hidden||procedureRunning||$('modal').open)return;const s=sim.s;for(let i=0;i<BUBBLES.length;i++){if(bubbleBeat&(1<<i))continue;let ok=false;try{ok=BUBBLES[i][0](s);}catch{}if(ok){bubbleBeat|=1<<i;teamBubble(BUBBLES[i][1],BUBBLES[i][2]);return;}}}
setInterval(bubbleTick,1500);
/* Idle nudges: one small, generic question when the leader has done nothing for a while. Never names the diagnosis. */
const IDLE_HINTS=[
 [s=>!s.pulse&&!s.cpr&&!s.clear&&s.firstCPR!==null,'No one is compressing right now.','resus'],
 [s=>!s.monitor,'Is the monitor attached yet?','assess'],
 [s=>!s.pulse&&!s.pads,'Are the pads on the chest?','electrical'],
 [s=>!s.access&&!s.ivPending,'Does the team have IV / IO access?','meds'],
 [s=>!s.pulse&&!s.bvm,'Who is giving the breaths?','resus'],
 [s=>s.intubated&&!s.capno,'How do we know the tube is in the right place?','resus'],
 [s=>!s.history,'Has anyone asked the family what happened?','investigate'],
 [s=>!s.pulse&&s.cpr&&s.fatigued,'Your compressor looks tired.','resus'],
 [s=>!s.pulse&&s.cpr&&s.cycle>85&&s.cycle<118,'Rhythm check is coming — is the defibrillator ready?','electrical'],
 [s=>!s.pulse&&!(s.labs||s.labPending?.length),'Any bedside tests worth sending during CPR?','investigate'],
 [s=>s.pulse&&!s.rosc&&!s.exam,'Stable or unstable? Reassess the patient.','investigate'],
 [s=>!s.pulse&&s.cpr,'Think Hs & Ts — what could be reversible here?','investigate'],
 [s=>!s.pulse&&s.cpr,'Coach the compressions while you wait.','cpr-game'],
 [s=>!s.pulse&&s.cpr&&s.monitor&&!s.flatline&&s.rhythm==='ASYSTOLE'&&s.checkedRhythm==='ASYSTOLE','Is that line really flat? Prove it.','flatline-game'],
 [s=>!s.pulse&&s.cpr&&s.access,'Is the next drug due soon?','meds'],
 [s=>s.rosc&&!s.post,'Recheck the pulse and plan ongoing care.','post']];
function idleHintTick(){if(!sim||screen!=='play')return;if(tut){$('idle-hint').hidden=true;return;}const s=sim.s,h=$('idle-hint');if(s.ended||s.paused||panel||procedureRunning||$('modal').open||document.getElementById('ht-window')||document.getElementById('fl-game')||document.getElementById('proc-screen')){if(panel||s.paused||s.ended)h.hidden=true;return;}
 const idle=s.t-Math.max(lastPlayerAt,idleHintAt);if(!h.hidden&&s.t-idleHintAt>14)h.hidden=true;if(idle<(!s.pulse&&!s.cpr&&s.firstCPR!==null?8:20))return;
 const ok=IDLE_HINTS.map((x,i)=>[x,i]).filter(([x])=>{try{return x[0](s);}catch{return false;}});if(!ok.length)return;const first=ok.find(([,i])=>i<10);const pick=first&&idleHintIndex%3!==2?first:ok[idleHintIndex%ok.length];idleHintIndex++;
 idleHintAt=s.t;h.textContent='💭 '+pick[0][1];h.dataset.go=pick[0][2];h.hidden=false;if(sound)tone(660,.05,.04,'sine');}
$('idle-hint').onclick=()=>{const go=$('idle-hint').dataset.go;markPlayerAction();$('idle-hint').hidden=true;go==='cpr-game'?openPractice('cpr'):go==='flatline-game'?flatlineGame():openPanel(go);};
setInterval(idleHintTick,1000);document.querySelector('.vital.white')?.addEventListener('click',()=>{if(sim&&!sim.s.capno)orderAction('etco2');});
$('resume-cpr').onclick=()=>{soundInit();if(sim?.s.paused&&!sim.s.ended){sim.s.paused=false;sim.log('resume','Practice resumed');}orderAction('resume-cpr');};
$('sound-toggle').onclick=()=>{settings.sound=!settings.sound;soundInit();localStorage.setItem('resus-settings',JSON.stringify(settings));update();beep();};

$('orbit-left').onclick=()=>ward?.orbitBy(-Math.PI/6);$('orbit-right').onclick=()=>ward?.orbitBy(Math.PI/6);$('zoom-in').onclick=()=>ward?.orbitBy(0,0,.85);$('zoom-out').onclick=()=>ward?.orbitBy(0,0,1.15);$('role-labels').onclick=()=>{if(!ward)return;ward.labelsVisible=!ward.labelsVisible;$('role-labels').setAttribute('aria-pressed',String(ward.labelsVisible));};
$('camera-nav').onclick=e=>{const b=e.target.closest('[data-camera]');if(!b)return;userPreset=b.dataset.camera;clearTimeout(camTimer);ward?.cameraPreset(b.dataset.camera);$('camera-nav').querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b));};
$('pause-btn').onclick=()=>{if(!sim||sim.s.ended)return;sim.s.paused=!sim.s.paused;sim.log('pause',sim.s.paused?'Practice paused • Timer stopped':'Resume scenario');update();};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&sim&&!sim.s.ended&&!sim.s.paused){sim.s.paused=true;sim.log('background-pause','Automatically paused when leaving the app • Press ▶ to resume');saveSession();}});
function openModal(title,html){$('modal-title').textContent=title;$('modal-content').innerHTML=html;modalPaused=!!(sim&&!sim.s.paused&&!sim.s.ended);if(modalPaused){sim.s.paused=true;sim.log('reference-pause','Reference / guide opened • Practice timer paused');}if(!$('modal').open)$('modal').showModal();$('modal-content').scrollTop=0;}
function closeModal(){$('modal').close();if(modalPaused&&sim&&!sim.s.ended)sim.s.paused=false;modalPaused=false;update();}
function dismissModal(){closeModal();if(screen==='report')home();}
$('modal-close').onclick=dismissModal;$('modal').addEventListener('cancel',e=>{e.preventDefault();dismissModal();});
function evidence(){openModal('Clinical sources · AHA 2025',`<p>Clinical rules reference AHA 2025. Scenario timing and outcomes are scripted teaching conventions, not predictions for real patients.</p><ul>${Object.entries(SOURCES).map(([k,v])=>`<li><a href="${v}" target="_blank" rel="noopener">${escape(k)} · AHA 2025</a></li>`).join('')}</ul><div class="info-box warn">Hyperkalemic arrest: the effectiveness of IV calcium, bicarbonate, and insulin/glucose is not well established in AHA 2025. These treatments are not required to guarantee ROSC in this game.</div><p>Post-ROSC: SpO₂ 90–98% after reliable measurement, PaO₂ 60–105 mmHg, MAP ≥65, PaCO₂ 35–45. For patients unresponsive to verbal commands, maintain temperature control at 32–37.5°C for at least 36 h.</p><p class="preview-note">Expert and investigator review is required before research data collection.</p>`);}
/* How to play. Written for a first-time player: pictures-and-verbs, one idea per card, and the same
   order they will meet things in a case. English and Thai say the same thing. */
