$('manual-btn').onclick=manual;$('home-manual').onclick=manual;
$('settings-btn').onclick=()=>{openModal('Graphics, audio, and accessibility',`<div class="fields"><label class="full">Graphics quality<select id="quality"><option value="low">Performance · Reduced shadows</option><option value="standard">Standard · Recommended</option><option value="high">Enhanced · Supported devices</option></select></label><label class="full">Motion<select id="motion"><option value="normal">Smooth camera</option><option value="reduced">Reduce motion</option></select></label><label class="full">Audio<select id="audio-setting"><option value="off">Sound off</option><option value="on">Equipment sounds on</option></select></label></div><p>All graphics levels use the same clinical rules and information. Reduced motion stops idle sway, decorative blinking and family talking, and removes camera travel. CPR, breathing and procedure animations remain visible to communicate team activity.</p><button class="primary" id="save-settings">Save</button><button id="last-report" style="margin-left:8px">Latest practice result</button>`);$('quality').value=settings.quality;$('motion').value=settings.reduced?'reduced':'normal';$('audio-setting').value=settings.sound?'on':'off';$('save-settings').onclick=()=>{settings={font:'classic',quality:$('quality').value,reduced:$('motion').value==='reduced',sound:$('audio-setting').value==='on'};applyGlass();try{localStorage.setItem('resus-settings',JSON.stringify(settings));}catch{}ward?.setQuality(settings.quality);if(ward)ward.reduced=settings.reduced;soundInit();closeModal();};$('last-report').onclick=()=>{try{const r=JSON.parse(localStorage.getItem('resus-last-session'));if(!r)return toast('No saved practice result yet.');if(r.version!==VERSION)return toast('The saved result belongs to an earlier build. Start a new session to generate an English report.');closeModal();reportModal(r);}catch{toast('Unable to read the latest result.');}};};
$('hint-btn').onclick=()=>{if(sim)sim.action('hint');};
$('events-btn').onclick=()=>{if(!sim)return;openModal('Event timeline',sim.events.map(e=>`<div class="event ${e.kind}"><time>${fmt(e.t)}</time><span>${escape(e.text)}</span></div>`).join(''));};
$('ecg-expand').onclick=()=>{if(!sim)return;openModal('Rhythm review',`<canvas id="review-ecg" style="width:100%;height:200px"></canvas><p>Interpret ECG alongside pulse and clinical findings. A tracing alone cannot diagnose PEA.</p>`);const t=new Trace($('review-ecg'),{paper:true});requestAnimationFrame(()=>{t.resize();t.draw(0,displayRhythm(sim.s),sim.s.hr,{pacerRate:sim.s.pacerRate||70,active:sim.s.monitor,staticStrip:true});t.observer.disconnect();});};
$('debrief-btn').onclick=()=>{if(!sim)return;openModal('Finish and review practice',`<p>You can save your actions and open the debrief even before completing the scenario.</p><button class="primary" id="finish-confirm">End scenario / termination discussion</button>`);$('finish-confirm').onclick=()=>{closeModal();finish();};};
function finish(){if(!sim)return;if(!sim.s.ended)sim.end('stopped');saveSession();showReport();}
function showReport(){if(!sim)return;closePanel();screen='report';saveSession();reportModal(currentReport());}
function personalHtml(r,goals){const f=personalFeedback(r,goals);return `<section class="pf"><h3>Your personal feedback</h3><p class="pf-head">${escape(f.headline)}</p><div class="pf-bars">${f.domains.map(d=>`<div class="pf-bar"><span>${d.label}</span><i><b style="width:${d.value}%" class="${d.value>=80?'hi':d.value>=55?'mid':'lo'}"></b></i><em>${d.value}</em></div>`).join('')}</div><div class="pf-cols"><div><h4>What you did well</h4>${f.strengths.length?'<ul>'+f.strengths.map(t=>`<li>${escape(t)}</li>`).join('')+'</ul>':'<p>Keep going — strengths appear here as soon as your timings and decisions show them.</p>'}</div><div><h4>Your priorities</h4>${f.improve.length?'<ol>'+f.improve.map(i=>`<li><b>${escape(i.text)}</b>${i.tip?`<span>${escape(i.tip)}</span>`:''}</li>`).join('')+'</ol>':'<p>Nothing to correct on this path.</p>'}</div></div><p class="pf-drill">${escape(f.drill)}</p></section>`;}
function postReviewHtml(r){const items=r.postReview;if(!items)return '';const wrong=items.filter(i=>!i.ok);return `<div class="post-review ${wrong.length?'has-wrong':'all-right'}"><h3>Post-ROSC targets ${wrong.length?'— please review AHA 2025':'— all correct ✓'}</h3><table><tr><th></th><th>Your answer</th><th>AHA 2025 target</th></tr>${items.map(i=>`<tr class="${i.ok?'ok':'bad'}"><td>${i.ok?'✓':'✗'} ${i.k}</td><td>${i.v||'—'} ${i.u}</td><td>${i.target}</td></tr>`).join('')}</table>${wrong.length?`<ul>${wrong.map(i=>`<li><b>${i.k}:</b> ${escape(i.note)}</li>`).join('')}</ul><p><b>What changed in 2025:</b> temperature control is now 32–37.5 °C for at least 36 h (2020: 32–36 °C for at least 24 h), and the SpO₂ target is 90–98 % (2020: 92–98 %).</p>`:''}</div>`;}
function reportModal(r){const achieved=new Set(r.achieved||[]),c=CASES[r.scenario-1];const goalLabels={"assess":"Assess pulse / breathing","monitor":"Attach monitor","history":"Take history","exam":"Examine patient","cause":"Identify a cause with supporting evidence","flatline":"Confirm the non-shockable rhythm (flat-line protocol)","cpr":"Start CPR","pads":"Apply defibrillation pads","shock":"Deliver an indicated shock","epi":"Give indicated epinephrine","anti":"Use an accepted antiarrhythmic","bvm":"Provide bag-mask ventilation","glucose":"Treat documented hypoglycemia","fluids":"Assess and administer fluids","vagal":"Vagal maneuver","adenosine":"Give indicated adenosine","reassess":"Reassess after clinical deterioration","ecg12":"12-lead ECG","atropine":"Give indicated atropine","stabilization":"Verify mechanical capture or use infusion support","cath":"Arrange definitive care","patch":"Find and remove the opioid patch","naloxone":"Opioid antagonist with ventilation support","infusion":"Plan infusion and monitor recurrent toxicity","post":"Ongoing care and handover"};const goals=Object.entries(RUBRICS[r.scenario]||{}).map(([key,points])=>[key,goalLabels[key]||key,points]);const isAchieved=key=>key==='stabilization'?(achieved.has('capture')||achieved.has('brady-infusion')):achieved.has(key);const catMood=!r.completed?'cry':r.score>=90?'party':r.score>=70?'proud':'worried',catLine=!r.completed?'You left before handover… I’m not crying, it’s just… allergies 😿 Try again?':r.score>=90?`${r.score} points?! I’m telling every cat in the hospital 🎉`:r.score>=70?'Solid code! A few things to polish — read below 😼':'We got there… but my whiskers are trembling 🙀 Let’s review together.';
 openModal(r.completed?'Debrief · Scenario completed':'Debrief · Practice review',`<div class="debrief-cat">${mascotSVG(catMood)}<p><b>ROSCo:</b> ${catLine}</p></div><h2>${r.completed?(r.score>=85?'Excellent work':'Well done'):'Practice stopped'}, ${escape(r.playerName||'learner')}${r.completed?'!':'.'}</h2><p>${r.completed?'You finished the case and handed over. Review your decisions and next steps below.':'The case was not finished — no handover yet. See what was done, what was missed, and try again.'}</p><small>CASE 0${r.scenario} · ${escape(c?.title||'')}</small><h3>${r.completed?'What your decisions taught you':'Review before trying again'}</h3><div class="report-metrics"><div><b>${fmt(r.simulationSeconds)}</b><small>SIMULATION TIME · ${r.simulationSpeed||1}×</small></div><div><b>${r.ccf??'—'}${r.ccf==null?'':'%'}</b><small>COMPRESSION FRACTION</small></div><div><b>${r.score}</b><small>LEARNING POINTS / 100</small></div><div><b>${fmt(r.firstShock)}</b><small>FIRST SHOCK</small></div><div><b>${fmt(r.firstEpi)}</b><small>FIRST EPINEPHRINE</small></div><div><b>${r.hints}</b><small>HINTS USED</small></div><div><b>${r.cprInTarget??'—'}${r.cprInTarget==null?'':'%'}</b><small>CPR IN TARGET RATE / DEPTH</small></div></div>${personalHtml(r,goals)}${postReviewHtml(r)}<h3>Learning objectives</h3><ul class="checklist">${goals.map(([key,text,points])=>`<li class="${isAchieved(key)?'done':''}">${isAchieved(key)?'✓':'○'} ${text} <small>(${isAchieved(key)?points:0}/${points})</small></li>`).join('')}</ul><p>Points reflect case-specific objectives minus recorded error penalties. They are not a validated research knowledge score.</p><h3>Interpretation and coaching</h3><p>Rhythm identification: ${(r.rhythmAnswers||[]).filter(a=>a.correct).length} / ${(r.rhythmAnswers||[]).length} correct (not part of the point rubric).</p>${(r.rhythmAnswers||[]).map(a=>`<p>${fmt(a.t)} · ${escape(a.choice)} · ${a.correct?'Correct':'Review interpretation'}</p>`).join('')}${(r.hintEvents||[]).map(e=>`<p>Hint ${fmt(e.t)}: ${escape(e.text)}</p>`).join('')}<p>${r.scenario===4?'Electrical capture alone does not prove perfusion. Check that palpable pulses match the paced rate and blood pressure improves.':r.scenario===5?'During arrest, CPR, ventilation and standard ACLS take priority. Naloxone must not delay them and is not required for simulated ROSC.':r.scenario===1?'Hyperkalemic arrest therapies have uncertain benefit in AHA 2025. Continue standard resuscitation and plan potassium reassessment and definitive renal care.':''}</p><h3>What to practice next</h3>${r.errors.length?'<ul>'+r.errors.slice(-5).map(e=>`<li>${escape(e.text)}</li>`).join('')+'</ul>':'<p>No protocol errors were recorded on this path. Review incomplete objectives and the reasoning behind each decision.</p>'}<div class="info-box">${escape(c?.objective||'')}<br>Outcomes are scripted simulations, not survival predictions. Game points are not validated research outcomes.</div><p><small>Game build: ${escape(r.buildId||'Unrecorded in this older report')}</small></p><div class="report-actions"><button id="export-json">Export JSON</button><button id="export-csv">Export CSV</button><button id="report-events">View timeline</button><button id="report-home" class="primary">Return to practice room</button></div>`);$('export-json').onclick=()=>download(JSON.stringify(r,null,2),`resus-case${r.scenario}-${r.session}.json`,'application/json');$('export-csv').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const lines=[['session','version','build_id','player_name','simulation_speed','case','seconds','action','rhythm','pulse','kind','text'],...r.events.map(e=>[r.session,r.version,r.buildId||'unrecorded',r.playerName||'',r.simulationSpeed||1,r.scenario,e.t,e.action,e.rhythm,e.pulse,e.kind,e.text])];download('\ufeff'+lines.map(row=>row.map(cell).join(',')).join('\r\n'),`resus-case${r.scenario}.csv`,'text/csv');};$('report-events').onclick=()=>{closeModal();openModal('Event timeline',r.events.map(e=>`<div class="event ${e.kind}"><time>${fmt(e.t)}</time><span>${escape(e.text)}</span></div>`).join('')+'<button id="timeline-back" class="primary wide">Back to debrief</button>');$('timeline-back').onclick=()=>{closeModal();reportModal(r);};};$('report-home').onclick=()=>{closeModal();home();};}
function download(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
/* Instructor lock: the home screen stays "not in use" until the passcode is entered on this device. This is a classroom gate, not security. */
const LOCK_KEY='acls-sim-active',LOCK_CODE='123456';let lockMemory=false;
function gameActive(){try{return localStorage.getItem(LOCK_KEY)==='1';}catch{return lockMemory;}}
function setGameActive(on){lockMemory=on;try{on?localStorage.setItem(LOCK_KEY,'1'):localStorage.removeItem(LOCK_KEY);}catch{}applyLock();}
function applyLock(){const on=gameActive();document.body.classList.toggle('game-locked',!on);$('lock-panel').hidden=on;$('lock-game').hidden=!on;if(!on){$('lock-code').value='';$('lock-msg').textContent='';}if(on&&screen==='home')setTimeout(homeCat,700);else if(!on)rosco.hide();}
$('lock-form').onsubmit=e=>{e.preventDefault();if($('lock-code').value.trim()===LOCK_CODE){setGameActive(true);}else{$('lock-msg').textContent='Incorrect passcode';$('lock-code').value='';$('lock-panel').classList.remove('shake');void $('lock-panel').offsetWidth;$('lock-panel').classList.add('shake');}};
$('lock-game').onclick=()=>setGameActive(false);
document.querySelector('.case-library').addEventListener('click',e=>{if(!gameActive()&&!e.target.closest('#lock-panel')){e.stopPropagation();e.preventDefault();$('lock-code').focus();}},true);
applyLock();
/* ── ROSCo the cat ───────────────────────────────────────────────────────────────────────────────
   The guide mascot: a dramatic black cat with yellow eyes. In the tutorial it walks the player through a real
   VF arrest step by step (Duolingo style: one instruction, one glowing target, a reaction when it is done).
   In the other cases and the Rhythm Lab it only reacts — briefly, and not too often. */
function mew(mood){if(!sound||!audio||audio.state!=='running')return;
 if(mood==='cry'){tone(560,.28,.05,'triangle',0,380);tone(420,.34,.045,'triangle',.26,300);return;}
 if(mood==='shocked'){tone(900,.07,.05,'square',0,1500);tone(1500,.12,.04,'triangle',.07,700);return;}
 if(mood==='party'||mood==='proud'){[784,988,1175,1568].forEach((f,i)=>tone(f,.1,.045,'triangle',i*.08));tone(700,.16,.05,'triangle',.34,1100);return;}
 if(mood==='worried'){tone(660,.14,.045,'triangle',0,560);tone(560,.14,.04,'triangle',.15,620);return;}
 tone(640,.16,.05,'triangle',0,1000);tone(1000,.2,.045,'triangle',.15,620);}
function homeCat(){if(screen!=='home')return;rosco.mount($('home'),'home').say(`Meow! I’m <b>ROSCo</b>, your resus buddy 🐾<br>New here? Start with the <b>Tutorial</b> — I’ll show you every button.`,{mood:'excited',actions:[['▶ Start tutorial',()=>{rosco.quiet();document.querySelector('[data-case="6"]')?.click();}],['Later',()=>rosco.say('Fine. I’ll be napping right here. 😼',{mood:'cool',ms:2200}),false]]});}
let catLastAt=0;
const CAT_LINES={good:[['Purr-fect! 😻','excited'],['YES! That’s my team leader!','excited'],['Textbook. I’m printing this on my scratching post.','proud'],['Nice! Keep going!','happy']],
 bad:[['NOOO 🙀 not like that!','shocked'],['I can’t watch… (peeks) …what are we doing?!','cry'],['Hiss! Check that again, boss.','worried'],['My nine lives just dropped to eight 😿','cry']],
 rosc:[['A PULSE!!! I’m not crying, YOU’RE crying 😭🎉','party']]};
function catReact(e){if(tut||!sim||screen!=='play'||rosco.el.hidden)return;const now=performance.now();
 const kind=['stabilize','rosc-confirmed'].includes(e.action)?'rosc':e.kind==='bad'&&e.action!=='rhythm-answer'?'bad':e.pointsEarned>=10?'good':null;if(!kind)return;
 if(kind!=='rosc'&&(now-catLastAt<14000||Math.random()<.4))return;catLastAt=now;const pool=CAT_LINES[kind],[m,mo]=pool[Math.floor(Math.random()*pool.length)];rosco.say(m,{mood:mo,ms:kind==='rosc'?5000:2800});}

/* Tutorial steps. target: a selector (or function) for the one button to press; panel: open that panel first;
   done(s): when the step is complete; after: [line, mood] said when it is done; skip: offer a fast-forward. */
let tut=null;
const tutDrugTarget=()=>!$('order-sheet')||$('order-sheet').hidden?'[data-drug="epinephrine"]':!$('dose-other')?.value?'#dose-other':'#give-order';
const tutPostTarget=()=>{for(const k of ['spo2','map','co2','temp','hours']){const f=$('post-'+k);if(f&&!f.value&&!f.closest('[hidden]'))return `[data-pq="${k}"][data-pqv="${{spo2:94,map:65,co2:40,temp:36,hours:36}[k]}"]`;}return '#handover';};
const TUT_STEPS=[
 {say:'Meow! I’m <b>ROSCo</b> 🐈‍⬛ Today <b>you</b> lead the team. You don’t do the work — you <b>give the orders</b>. I’ll point with my paw 🐾 every time. Ready?',mood:'excited',btn:'Let’s go!'},
 {say:'Someone just collapsed! 😱 Rule #1: check him. Open <b>Assess</b>, then tap <b>Pulse &amp; breathing</b> (10 seconds max).',mood:'worried',panel:'assess',target:'[data-action="pulse"]',done:s=>s.assessed,after:['NO PULSE! NOT BREATHING! 🙀 That’s cardiac arrest!','shocked']},
 {say:'Every second without CPR hurts the brain. Tap <b>▶ START CPR</b> — now, now, NOW!',mood:'worried',target:'#resume-cpr',done:s=>s.cpr,after:['Yesss! Push hard, push fast: 100–120 a minute 💪','excited']},
 {say:'Let’s see what the heart is doing. <b>Assess → Attach monitor</b>.',mood:'happy',panel:'assess',target:'[data-action="monitor"]',done:s=>s.monitor,after:['Monitor’s on — the trace is on the right 👉','happy']},
 {say:'Pro move: put the defib pads on <b>while CPR keeps going</b>, so the pause stays short. <b>Defib / Pacer → 1 Apply pads</b>.',mood:'happy',panel:'electrical',target:'[data-action="pads"]',done:s=>s.pads,after:['Pads on, and nobody stopped pushing 😼','proud']},
 {say:'To read the rhythm you must pause CPR <b>briefly</b> (under 10 s). Tap <b>⏸ Pause &amp; check rhythm</b>.',mood:'thinking',target:'#interpret-ecg',done:()=>!!document.querySelector('[data-identify]')||sim.s.rhythmAnswers.length>0},
 {say:'Wiggly chaos, no real beats… that’s <b>VF</b>! Tap <b>VF / pulseless VT</b>.',mood:'thinking',target:'[data-identify="shockable"]',done:s=>s.rhythmAnswers.filter(a=>a.correct).length>=1,after:['Correct! VF is SHOCKABLE ⚡','excited']},
 {say:'No pulse = <b>⚡ Defibrillation</b> (not sync). Energy <b>200 J</b>, then tap <b>CHARGE</b>. CPR keeps going while it charges!',mood:'happy',panel:'electrical',target:'#charge-btn',done:s=>s.charged||s.charge>0},
 {say:'It’s charging (3 s)… Shout <b>CLEAR</b> — everybody hands off the patient!',mood:'worried',panel:'electrical',target:'#defib-clear',done:s=>s.clear,after:['CLEEEAR! 🙀 (I’m hiding behind the monitor)','shocked']},
 {say:'Now: <b>SHOCK</b>!',mood:'shocked',panel:'electrical',target:'#defib-shock',done:s=>s.shocks>=1,after:['BZZZT ⚡⚡ Nice shock!','party']},
 {say:'Don’t stop to admire it — <b>straight back to CPR</b>. No pulse check yet!',mood:'worried',target:'#resume-cpr',done:s=>s.cpr,after:['Good. Shock → CPR, every time.','proud']},
 {say:'Drugs need a way in. <b>Med cart → Intraosseous (IO)</b> — the fastest in arrest.',mood:'happy',panel:'meds',target:'[data-action="insert-io"]',done:s=>s.iv||!!s.ivPending,after:['IO going in… 🦴 ready in about 10 seconds.','happy']},
 {say:'While CPR runs, play detective 🕵️ <b>Investigate → Ask the family</b> what happened.',mood:'thinking',panel:'investigate',target:'[data-action="history"]',done:s=>s.history,after:['Crushing chest pain before he collapsed… suspicious 🤔 Remember that!','thinking']},
 {say:'Now <b>2 minutes</b> of great CPR. (Tip: in real cases you can coach CPR with the tap game.) Let’s fast-forward ⏩',mood:'cool',skip:true,btn:'⏩ Skip to the 2-minute mark',done:s=>s.cycle>=118},
 {say:'Two minutes! <b>⏸ Pause &amp; check rhythm</b> again.',mood:'thinking',target:'#interpret-ecg',mark:true,done:s=>s.lastRhythmCheckAt>tut.mark},
 {say:'Still VF 😾 Same answer: <b>VF / pulseless VT</b>.',mood:'worried',target:'[data-identify="shockable"]',done:s=>s.rhythmAnswers.filter(a=>a.correct).length>=2},
 {say:'Shock #2: <b>200 J → CHARGE</b>.',mood:'happy',panel:'electrical',target:'#charge-btn',done:s=>s.charged||s.charge>0},
 {say:'<b>CLEAR!</b>',mood:'worried',panel:'electrical',target:'#defib-clear',done:s=>s.clear},
 {say:'<b>SHOCK!</b> (if it isn’t charged yet, wait a second and tap again)',mood:'shocked',panel:'electrical',target:'#defib-shock',done:s=>s.shocks>=2,after:['⚡⚡ Two shocks in!','excited']},
 {say:'Back to <b>CPR</b>!',mood:'worried',target:'#resume-cpr',done:s=>s.cpr},
 {say:'After the 2nd shock comes <b>epinephrine 1 mg</b>. <b>Med cart</b> → tap it → <b>type 1</b> → <b>Give</b>.',mood:'happy',panel:'meds',target:tutDrugTarget,done:s=>s.epi,after:['Epi in! 💉 Repeat every 3–5 minutes from now on ⏰','excited']},
 {say:'Another 2 minutes of CPR… ⏩',mood:'cool',skip:true,btn:'⏩ Skip to the 2-minute mark',done:s=>s.cycle>=118||s.roscReady},
 {say:'Moment of truth 😬 <b>⏸ Pause &amp; check rhythm</b>.',mood:'worried',target:'#interpret-ecg',done:s=>s.rosc,after:['Organised rhythm AND a pulse!!! ROSC!!! 🎉 I’m not crying, YOU’RE crying 😭','party']},
 {say:'Now we look after him. <b>Handover → Recheck pulse</b>.',mood:'happy',panel:'post',target:'[data-action="pulse"]',mark:true,done:s=>s.assessed},
 {say:'Does he follow commands? Tap <b>Assess verbal commands</b>.',mood:'thinking',panel:'post',target:'[data-action="commands"]',done:s=>s.commandsChecked},
 {say:'What caused it? Remember the chest pain… → <b>Thrombosis · coronary</b>.',mood:'thinking',panel:'post',target:'[data-cause-pick="coronary"]',done:s=>s.cause,after:['Detective cat approves 🕵️‍♂️','proud']},
 {say:'Last bit! Tap the AHA targets: <b>SpO₂ 94</b>, <b>MAP 65</b>, <b>PaCO₂ 40</b>, <b>36 °C</b>, <b>36 h</b> — then <b>Handover</b>.',mood:'excited',panel:'post',target:tutPostTarget,done:s=>s.ended}];
function tutStop(){tut=null;document.querySelectorAll('.tut-target').forEach(e=>e.classList.remove('tut-target'));document.getElementById('tut-bar')?.remove();}
function tutStart(){if(!sim||!sim.c.tutorial)return;tut={i:-1,mark:0,shownAt:0};const bar=document.createElement('div');bar.id='tut-bar';bar.className='tut-bar';bar.innerHTML='<span>🐾 TUTORIAL</span><div class="tut-prog"><i></i></div><button type="button" id="tut-quit">Exit</button>';$('stage').appendChild(bar);$('tut-quit').onclick=()=>{tutStop();rosco.say('Okay, you’re on your own now. I believe in you! 😼',{mood:'cool',ms:3000});};tutNext();}
function tutNext(){if(!tut)return;tut.i++;const st=TUT_STEPS[tut.i];if(!st){tutStop();return;}if(st.mark)tut.mark=sim.s.t;
 const pr=document.querySelector('#tut-bar .tut-prog i');if(pr)pr.style.width=Math.round(100*tut.i/(TUT_STEPS.length-1))+'%';
 const actions=st.btn?[[st.btn,()=>{if(st.skip)tutSkip();else{rosco.quiet();tutNext();}}]]:[];
 rosco.say(st.say,{mood:st.mood,actions});tut.shownAt=performance.now();tutPaint();}
function tutSkip(){if(!sim)return;if(!sim.s.cpr)orderAction('resume-cpr');let n=0;while(sim.s.cycle<118.5&&!sim.s.roscReady&&n++<1500)sim.tick(.1);if(sim.s.roscReady)while(sim.s.cycle<118.5&&n++<3000)sim.tick(.1);update();}
function tutPaint(){if(!tut)return;const st=TUT_STEPS[tut.i];if(!st||!sim)return;
 let sel=typeof st.target==='function'?st.target():st.target;if(st.panel&&panel!==st.panel)sel=`#dock [data-panel="${st.panel}"]`;
 const el=sel?[...document.querySelectorAll(sel)].find(e=>e.offsetParent):null;if(el&&el.classList.contains('tut-target'))return;document.querySelectorAll('.tut-target').forEach(e=>e.classList.remove('tut-target'));if(el){el.classList.add('tut-target');if(el.closest('#drawer')&&!el.dataset.tutSeen){el.dataset.tutSeen=1;el.scrollIntoView({block:'center',behavior:'smooth'});}}}
function tutTick(){if(!tut||!sim)return;const st=TUT_STEPS[tut.i];if(!st)return;
 if(st.done&&performance.now()-tut.shownAt>350&&st.done(sim.s)){if(st.after){const [m,mo]=st.after;rosco.say(m,{mood:mo});tut.shownAt=performance.now();setTimeout(()=>{if(tut&&TUT_STEPS[tut.i]===st)tutNext();},st.after[1]==='party'?2600:1700);tut.shownAt=Infinity;}else tutNext();return;}
 tutPaint();}
/* ── Rhythm Lab as a game ─────────────────────────────────────────────────────────────────────
   Each strip prints in like a monitor, beeping on every QRS — so AF sounds irregular, CHB sounds slow and
   flutter sounds metronome-regular — then a 25-second clock runs. Correct = 100, plus up to 50 for speed,
   times a streak multiplier (×1.25 per answer in a row, up to ×2). The reasoning always shows after. */
const LAB_SECS=25,LAB_PRINT=3.2,LAB_STRIP=10;
let lab={score:0,streak:0,bestStreak:0,results:[],raf:0,t0:0,beats:[],beatIx:0,answeredAt:0,tick:-1};
function labBeats(r){const out=[];let prev=-1,last=-9;const step=.002;for(let t=0;t<=LAB_STRIP;t+=step){const v=waveform(t,r.id,r.hr),n=waveform(t+step,r.id,r.hr);if(v>.55&&v>=prev&&v>n&&t-last>.22){out.push(t);last=t;}prev=v;}return out;}
function labHud(){$('lab-score').textContent=lab.score;$('lab-streak').textContent=lab.streak>1?`🔥 ${lab.streak} in a row · ×${Math.min(2,1+.25*(lab.streak-1)).toFixed(2)}`:'';
 $('lab-dots').innerHTML=TRAINER_SET.map((_,k)=>`<i class="${lab.results[k]===true?'ok':lab.results[k]===false?'no':k===trainerIndex?'now':''}"></i>`).join('');}
function labLoop(){cancelAnimationFrame(lab.raf);const r=trainerDeck[trainerIndex];
 const step=()=>{const el=(performance.now()-lab.t0)/1000,reveal=Math.min(LAB_STRIP,el*LAB_STRIP/LAB_PRINT);
  trainerTrace.draw(0,r.id,r.hr,{staticStrip:true,reveal});
  while(lab.beatIx<lab.beats.length&&lab.beats[lab.beatIx]<=reveal){beep(r.id==='PACED'||r.id==='PACED_NO_CAPTURE'?1300:960,.05,.03);lab.beatIx++;}
  if(r.id==='ASYSTOLE'&&reveal<LAB_STRIP&&Math.floor(el*4)%4===0&&lab.tick!==-2){lab.tick=-2;tone(700,LAB_PRINT,.025,'sine');}
  if(!trainerAnswered){const left=LAB_SECS-Math.max(0,el-LAB_PRINT);const bar=$('lab-timer');bar.style.setProperty('--left',Math.max(0,left/LAB_SECS));bar.classList.toggle('low',left<=5);
   $('lab-time').textContent=el<LAB_PRINT?'printing…':Math.ceil(Math.max(0,left))+' s';
   const whole=Math.ceil(left);if(left<=5&&left>0&&whole!==lab.tick){lab.tick=whole;tone(1568,.05,.03,'square');}
   if(left<=0){labAnswer(null);}}
  if(reveal<LAB_STRIP||!trainerAnswered)lab.raf=requestAnimationFrame(step);};
 lab.raf=requestAnimationFrame(step);}
function labReplay(){lab.t0=performance.now()-(trainerAnswered?0:0);lab.beatIx=0;lab.tick=-1;labLoop();}
function trainerRound(){trainerAnswered=false;$('trainer-next').hidden=true;$('trainer-feedback').textContent='';$('trainer-feedback').className='';const r=trainerDeck[trainerIndex];
 $('trainer-progress').textContent=`${String(trainerIndex+1).padStart(2,'0')} / ${TRAINER_SET.length}`;
 const options=shuffled([r,...shuffled(TRAINER_SET.filter(x=>x!==r)).slice(0,3)]);$('trainer-options').innerHTML=options.map(x=>`<button data-rhythm="${x.id}">${escape(x.name)}</button>`).join('');
 lab.beats=labBeats(r);lab.beatIx=0;lab.tick=-1;lab.t0=performance.now();labHud();requestAnimationFrame(()=>{trainerTrace.resize();labLoop();});}
function labAnswer(id){if(trainerAnswered)return;trainerAnswered=true;const r=trainerDeck[trainerIndex],ok=id===r.id,el=(performance.now()-lab.t0)/1000,left=Math.max(0,LAB_SECS-Math.max(0,el-LAB_PRINT));
 let gained=0;if(ok){lab.streak++;lab.bestStreak=Math.max(lab.bestStreak,lab.streak);const mult=Math.min(2,1+.25*(lab.streak-1)),speed=Math.round(50*left/LAB_SECS);gained=Math.round((100+speed)*mult);lab.score+=gained;trainerScore++;}else lab.streak=0;
 lab.results[trainerIndex]=ok;
 $('trainer-options').querySelectorAll('button').forEach(x=>{x.disabled=true;x.classList.toggle('correct',x.dataset.rhythm===r.id);});
 const picked=id&&$('trainer-options').querySelector(`[data-rhythm="${id}"]`);if(picked&&!ok)picked.classList.add('wrong');
 if(sound){if(ok)(lab.streak>=3?SFX.combo():SFX.good());else SFX.wrong();}
 rosco.say(ok?(lab.streak>=5?'🔥🔥 Are you secretly a cardiologist?!':lab.streak>=3?'ON FIRE! 🔥':['Purr-fect! 😻','Yes! Big brain cat energy.','Correct! *happy tail wiggle*'][trainerIndex%3]):id?['Nooo 😿 read why below, then the next one!','Hiss… so close. Check the explanation 👇','My whiskers… 🙀 look at the P waves again.'][trainerIndex%3]:'Time’s up! ⏰ I fell asleep waiting 😴',{mood:ok?(lab.streak>=3?'party':'excited'):id?'cry':'cool',ms:2600,sound:false});
 const pop=$('lab-pop');pop.textContent=ok?`+${gained}`:id?'✗':'⏱ time';pop.className='lab-pop '+(ok?'ok':'no');void pop.offsetWidth;pop.classList.add('show');
 $('trainer-feedback').className=ok?'ok':'no';
 $('trainer-feedback').innerHTML=`<b>${ok?(lab.streak>=3?'On fire! ':'Correct · '):id?'Not quite · ':'Time is up · '}${escape(r.name)}</b><br>${escape(r.reason)}<br><small>Read in order: Rate → Regularity → P → PR → QRS → Clinical context</small> <button type="button" id="lab-replay" class="text-btn">▶ Replay with sound</button>`;
 $('lab-replay').onclick=labReplay;$('lab-time').textContent=ok?'✓':'✗';$('lab-timer').style.setProperty('--left',0);
 $('trainer-next').hidden=false;$('trainer-next').textContent=trainerIndex===TRAINER_SET.length-1?'See your result →':'Next tracing →';labHud();}
const LAB_RANKS=[[.95,'ECG Ninja 🥷'],[.8,'Rhythm Resident'],[.6,'Strip Reader'],[.4,'Junior Extern'],[0,'Rhythm Rookie']];
$('trainer-launch').onclick=()=>{soundInit();rosco.mount(document.body,'lab').say('Rhythm Lab! 👂 Listen to the beeps: AF sounds drunk, heart block sounds sleepy 😴, flutter sounds like a metronome.',{mood:'excited',ms:6000});trainerIndex=0;trainerScore=0;lab={...lab,score:0,streak:0,bestStreak:0,results:[]};trainerDeck=shuffled(TRAINER_SET);showScreen('trainer');trainerRound();};
$('trainer-exit').onclick=()=>{cancelAnimationFrame(lab.raf);rosco.quiet();home();};
$('trainer-options').onclick=e=>{const b=e.target.closest('[data-rhythm]');if(!b)return;labAnswer(b.dataset.rhythm);};
$('trainer-next').onclick=()=>{if(trainerIndex<TRAINER_SET.length-1){trainerIndex++;trainerRound();return;}
 cancelAnimationFrame(lab.raf);const acc=trainerScore/TRAINER_SET.length,rank=LAB_RANKS.find(([m])=>acc>=m)[1];let best=0;try{best=+localStorage.getItem('acls-lab-best')||0;if(lab.score>best)localStorage.setItem('acls-lab-best',lab.score);}catch{}
 const missed=trainerDeck.filter((r,k)=>lab.results[k]===false);if(sound)SFX.rosc();
 openModal('Rhythm Lab · Result',`<div class="lab-result"><div class="lab-rank">${rank}</div><div class="lab-big">${lab.score}<small>points${lab.score>best?' · NEW BEST!':best?` · best ${best}`:''}</small></div>
 <div class="lab-stats"><p><b>${trainerScore}/${TRAINER_SET.length}</b><span>correct</span></p><p><b>${Math.round(acc*100)}%</b><span>accuracy</span></p><p><b>${lab.bestStreak}</b><span>best streak</span></p></div>
 ${missed.length?`<h3>Review these</h3><ul>${missed.map(r=>`<li><b>${escape(r.name)}</b> — ${escape(r.reason.split('. ')[0])}.</li>`).join('')}</ul>`:trainerScore===TRAINER_SET.length?'<p>Perfect run — every rhythm read correctly.</p>':''}
 <div class="lab-actions"><button id="lab-again" class="primary">Play again</button><button id="lab-finish">Choose a case</button></div></div>`);
 $('lab-again').onclick=()=>{closeModal();$('trainer-launch').click();};$('lab-finish').onclick=()=>{closeModal();home();};};
$('trainer-help').onclick=()=>openModal('Systematic ECG interpretation',`<ol><li><b>Rate:</b> Use the time scale and R–R intervals; markers are spaced one second apart.</li><li><b>Regularity:</b> Are the R–R intervals consistent?</li><li><b>P wave:</b> Are P waves visible and consistent in shape?</li><li><b>PR relationship:</b> Does each P wave lead to a QRS? Is there AV dissociation?</li><li><b>QRS:</b> Are complexes narrow or wide, and consistent in shape?</li><li><b>Clinical context:</b> Is there a pulse? Is the patient stable or unstable?</li></ol><p>The canvas simulates 25 mm/s and 10 mm/mV. Grid proportions are consistent, but screen squares are not physical millimeters on an iPad.</p>`);
let last=performance.now();function frame(now){requestAnimationFrame(frame);const elapsed=Math.max(0,(now-last)/1000),dt=Math.min(.1,elapsed);last=now;if(safetyRemaining>0){safetyRemaining=Math.max(0,safetyRemaining-elapsed);if(ward)ward.safetyRemaining=safetyRemaining;if(!safetyRemaining){$('stage').classList.remove('safety-event');$('start-case').click();}}if(sim&&screen==='play'){if(elapsed>3&&!sim.s.paused){sim.s.paused=true;sim.log('performance-pause','Automatically paused after a prolonged stall. Press ▶ to continue.');}else{let remaining=simulationDelta(elapsed,sim.s.paused||sim.s.ended);while(remaining>0){const step=Math.min(.1,remaining);sim.tick(step);remaining-=step;}}}renderClock+=dt;pulseOx(now);if(screen==='intro'&&!settings.reduced){const shot=Math.min(2,Math.floor((now-introAt)/3500));if(shot!==introShot){introShot=shot;ward?.cameraPreset(['intro','patient','overview'][shot]);$('intro-counter').textContent=`0${selected} · ${['ARRIVAL','ASSESS THE PATIENT','YOUR TEAM IS READY'][shot]}`;}}if(sim&&screen==='play'&&airwayProcedure.advance(simulationDelta(elapsed,sim.s.paused),sim.s)){sim.action('intubate');sayTeam('Airway: Tube is in. One breath every six seconds, ten a minute, and nobody stops compressions. Capnography, please.');teamBubble('airway','Tube is in! From now on: one breath every 6 seconds — 10 a minute — and we never stop pushing.','resus',9);refreshPanelSoon();}const procedure=airwayProcedure.snapshot();$('procedure-status').hidden=!procedure||screen!=='play';if(procedure){$('procedure-status').querySelector('span').textContent='AIRWAY · '+procedure.label;$('procedure-progress').value=procedure.progress;}const state=sim?{...sim.s,airwayProcedure:procedure}:{pulse:screen!=='intro'||selected>=3,conscious:screen!=='intro'||selected>=3,rr:14,unstable:false};if(ward)ward.sceneActive=screen==='play';ward?.update(dt,state);if(practiceUpdate&&screen==='play')practiceUpdate(simulationDelta(elapsed,sim.s.paused||sim.s.ended));if(screen==='play'&&sim){trace.draw(sim.s.t,displayRhythm(sim.s),sim.s.hr,{pacerRate:sim.s.pacerRate||70,active:sim.s.monitor,cpr:teamMotion(sim.s).compressing,sync:syncArmed});ward?.drawMonitor(sim.s);roomSound(sim.s,dt);if(reviewTrace)reviewTrace.draw(sim.s.t,displayRhythm(sim.s),sim.s.hr,{pacerRate:sim.s.pacerRate||70,active:sim.s.monitor,cpr:teamMotion(sim.s).compressing,sync:syncArmed});if(flTrace)flTrace.draw(sim.s.t,displayRhythm(sim.s),sim.s.hr,{pacerRate:sim.s.pacerRate||70,active:true,cpr:false});{const vm=ward?.visualMotion||teamMotion(sim.s),sp=vm.compressing?vm.strokePhase||0:0;if(sound&&vm.compressing&&!sim.s.paused&&!sim.s.ended&&compressionBeatAt<.36&&sp>=.36){tone(92,.16,.5,'sine',0,46);noiseBurst(.07,240,.7,.22,'lowpass');}compressionBeatAt=sp;}/* one deep thump as the hands reach full depth */}if(screen==='trainer'){const r=trainerDeck[trainerIndex];trainerTrace.draw(0,r.id,r.hr,{staticStrip:true});}}
showScreen('home');requestAnimationFrame(frame);
